const input = $input.first()?.json;
if (!input?.planetes?.output || !input?.maisons?.output?.Houses) return [{ json: { error: "Données manquantes" } }];

// 0. CAPTURE DES INFOS PERSOS
let perso = {};
try { perso = $("Extract Variables").first()?.json || {}; } catch(e){}

// ---- Sprint 5 — Paramètres forme & accessibilité (v6.4) ----
const consigneRedaction = perso.consigne_redaction || 'Tu';
const genreConsultant = perso.genre || 'M';
const langueRapport = perso.langue || 'Français';

// Étoiles fixes (transmises depuis 3c. via 4. Fusion Données)
const etoilesFixesRaw = (input.etoilesFixes?.output || []);

// 1. FILTRAGE ET NOMMAGE SÉCURISÉ DES NŒUDS
let rawPlanetes = input.planetes.output;
let hasTrueNode = rawPlanetes.some(p => {
    let n = (p.planet.en || p.planet.fr || "").toLowerCase();
    return n.includes("true") || n.includes("vrai");
});
let planetes = rawPlanetes.filter(p => {
    let n = (p.planet.en || p.planet.fr || "").toLowerCase();
    if (hasTrueNode && (n.includes("mean") || n.includes("moyen"))) return false;
    return true;
});
planetes = JSON.parse(JSON.stringify(planetes));

planetes.forEach(p => {
    let n = (p.planet.en || p.planet.fr || "").toLowerCase();
    if ((n.includes("node") || n.includes("nœud") || n.includes("noeud")) && !n.includes("anti")) {
        p.planet.fr = "Nœud Nord";
        p.planet.en = "North Node";
    }
});

let maisons = JSON.parse(JSON.stringify(input.maisons.output.Houses));

const signs = [
    {id:0,fr:"Bélier",ruler:"Mars"},{id:1,fr:"Taureau",ruler:"Vénus"},{id:2,fr:"Gémeaux",ruler:"Mercure"},{id:3,fr:"Cancer",ruler:"Lune"},
    {id:4,fr:"Lion",ruler:"Soleil"},{id:5,fr:"Vierge",ruler:"Mercure"},{id:6,fr:"Balance",ruler:"Vénus"},{id:7,fr:"Scorpion",ruler:"Pluton"},
    {id:8,fr:"Sagittaire",ruler:"Jupiter"},{id:9,fr:"Capricorne",ruler:"Saturne"},{id:10,fr:"Verseau",ruler:"Uranus"},{id:11,fr:"Poissons",ruler:"Neptune"}
];

// Décans Chaldéens — ordre planétaire descendant (Saturne→Jupiter→Mars→Soleil→Vénus→Mercure→Lune)
const CHALDEAN_DECANS = {
    "Bélier":["Mars","Soleil","Vénus"],"Taureau":["Mercure","Lune","Saturne"],
    "Gémeaux":["Jupiter","Mars","Soleil"],"Cancer":["Vénus","Mercure","Lune"],
    "Lion":["Saturne","Jupiter","Mars"],"Vierge":["Soleil","Vénus","Mercure"],
    "Balance":["Lune","Saturne","Jupiter"],"Scorpion":["Mars","Soleil","Vénus"],
    "Sagittaire":["Mercure","Lune","Saturne"],"Capricorne":["Jupiter","Mars","Soleil"],
    "Verseau":["Vénus","Mercure","Lune"],"Poissons":["Saturne","Jupiter","Mars"]
};

// Termes Égyptiens (Bounds) — 5 termes par signe [planète, degré_fin]
const EGYPTIAN_TERMS = {
    "Bélier":[["Jupiter",6],["Vénus",12],["Mercure",20],["Mars",25],["Saturne",30]],
    "Taureau":[["Vénus",8],["Mercure",14],["Jupiter",22],["Saturne",27],["Mars",30]],
    "Gémeaux":[["Mercure",6],["Jupiter",12],["Vénus",17],["Mars",24],["Saturne",30]],
    "Cancer":[["Mars",7],["Vénus",13],["Mercure",19],["Jupiter",26],["Saturne",30]],
    "Lion":[["Jupiter",6],["Vénus",11],["Saturne",18],["Mercure",24],["Mars",30]],
    "Vierge":[["Mercure",7],["Vénus",17],["Jupiter",21],["Mars",28],["Saturne",30]],
    "Balance":[["Saturne",6],["Mercure",14],["Jupiter",21],["Vénus",28],["Mars",30]],
    "Scorpion":[["Mars",7],["Vénus",11],["Mercure",19],["Jupiter",24],["Saturne",30]],
    "Sagittaire":[["Jupiter",12],["Vénus",17],["Mercure",21],["Saturne",26],["Mars",30]],
    "Capricorne":[["Mercure",7],["Jupiter",14],["Vénus",22],["Saturne",26],["Mars",30]],
    "Verseau":[["Mercure",7],["Vénus",13],["Jupiter",20],["Mars",25],["Saturne",30]],
    "Poissons":[["Vénus",12],["Jupiter",16],["Mercure",19],["Mars",28],["Saturne",30]]
};
const getTermRuler = (sign, deg) => {
    const terms = EGYPTIAN_TERMS[sign];
    if (!terms) return null;
    const d = deg % 30;
    for (const [ruler, boundary] of terms) { if (d < boundary) return ruler; }
    return terms[terms.length - 1][0];
};

const planetRulerships = {
    "Soleil":["Lion"],"Lune":["Cancer"],"Mercure":["Gémeaux","Vierge"],"Vénus":["Taureau","Balance"],
    "Mars":["Bélier","Scorpion"],"Jupiter":["Sagittaire","Poissons"],"Saturne":["Capricorne","Verseau"],
    "Uranus":["Verseau"],"Neptune":["Poissons"],"Pluton":["Scorpion"]
};

const dignities = {
    "Soleil":   { dom:["Lion"],                    exa:["Bélier"],    exi:["Verseau"],               chu:["Balance"] },
    "Lune":     { dom:["Cancer"],                  exa:["Taureau"],   exi:["Capricorne"],             chu:["Scorpion"] },
    "Mercure":  { dom:["Gémeaux","Vierge"],        exa:["Vierge"],    exi:["Sagittaire","Poissons"],  chu:["Poissons"] },
    "Vénus":    { dom:["Taureau","Balance"],        exa:["Poissons"],  exi:["Scorpion","Bélier"],      chu:["Vierge"] },
    "Mars":     { dom:["Bélier","Scorpion"],        exa:["Capricorne"],exi:["Balance","Taureau"],      chu:["Cancer"] },
    "Jupiter":  { dom:["Sagittaire","Poissons"],    exa:["Cancer"],    exi:["Gémeaux","Vierge"],       chu:["Capricorne"] },
    "Saturne":  { dom:["Capricorne","Verseau"],     exa:["Balance"],   exi:["Cancer","Lion"],          chu:["Bélier"] },
    "Uranus":   { dom:["Verseau"],                  exa:["Scorpion"],  exi:["Lion"],                   chu:["Taureau"] },
    "Neptune":  { dom:["Poissons"],                 exa:["Cancer"],    exi:["Vierge"],                 chu:["Capricorne"] },
    "Pluton":   { dom:["Scorpion"],                 exa:["Lion"],      exi:["Taureau"],                chu:["Verseau"] }
};

const getDignity = (planet, sign) => {
    if (!["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"].includes(planet)) return "-";
    let d = dignities[planet]; if (!d) return "-";
    if (d.dom.includes(sign)) return "Domicile";
    if (d.exa.includes(sign)) return "Exaltation";
    if (d.exi.includes(sign)) return "Exil";
    if (d.chu.includes(sign)) return "Chute";
    return "Pérégrine";
};

const elements = {
    "Feu":   ["Bélier","Lion","Sagittaire"],
    "Terre": ["Taureau","Vierge","Capricorne"],
    "Air":   ["Gémeaux","Balance","Verseau"],
    "Eau":   ["Cancer","Scorpion","Poissons"]
};
const modes = {
    "Cardinal": ["Bélier","Cancer","Balance","Capricorne"],
    "Fixe":     ["Taureau","Lion","Scorpion","Verseau"],
    "Mutable":  ["Gémeaux","Vierge","Sagittaire","Poissons"]
};

// 2. STATS ÉLÉMENTS & MODES
let stats = { elements: { Feu:0, Terre:0, Air:0, Eau:0 }, modes: { Cardinal:0, Fixe:0, Mutable:0 } };
let mainPoints = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Ascendant","Milieu du Ciel"];
planetes.forEach(p => {
    p.retroStr = p.isRetro?.toLowerCase().includes('true') ? " [Rétrograde]" : "";
    let name = p.planet.fr || p.planet.en;
    if (mainPoints.includes(name)) {
        let sign = p.zodiac_sign?.name?.fr;
        if (sign) {
            let el = Object.keys(elements).find(e => elements[e].includes(sign)); if(el) stats.elements[el]++;
            let mo = Object.keys(modes).find(m => modes[m].includes(sign)); if(mo) stats.modes[mo]++;
        }
    }
});

// 3. MAISONS UTILS
maisons.sort((a,b) => a.House - b.House);
function getHouseNumber(deg) {
    deg = ((deg % 360) + 360) % 360;
    for(let i=0; i<12; i++){
        let h1=maisons[i].degree, h2=maisons[(i+1)%12].degree;
        if((h1<h2 && deg>=h1 && deg<h2) || (h1>=h2 && (deg>=h1 || deg<h2))) return maisons[i].House;
    }
    return 1;
}

function angularDiff(a, b) {
    let d = Math.abs(a - b);
    return d > 180 ? 360 - d : d;
}

// 4. SECTE, NŒUD SUD, PART DE FORTUNE ET LOT DE L'ESPRIT
let asc  = planetes.find(p => p.planet.fr === "Ascendant");
let sun  = planetes.find(p => p.planet.fr === "Soleil");
let moon = planetes.find(p => p.planet.fr === "Lune");

let sunHouse  = sun ? getHouseNumber(sun.fullDegree) : 1;
// Calcul géométrique de la secte (plus précis que par numéro de maison)
// arc = ((sunDeg - ascDeg) + 360) % 360
//   arc < 180° → Soleil entre ASC et DSC (Maisons 1–6) = SOUS l'horizon → Nocturne
//   arc > 180° → Soleil entre DSC et ASC (Maisons 7–12) = AU-DESSUS de l'horizon → Diurne
let isDayChart;
if (asc && sun) {
    const arcSoleilDepuisAsc = ((sun.fullDegree - asc.fullDegree) + 360) % 360;
    isDayChart = arcSoleilDepuisAsc > 180;
} else {
    isDayChart = [7,8,9,10,11,12].includes(Number(sunHouse)); // fallback par maison
}
let sectStr = isDayChart ? "Diurne (Soleil au-dessus de l'horizon)" : "Nocturne (Soleil sous l'horizon)";
stats.sect = sectStr;
stats.sectLight   = isDayChart ? "Soleil" : "Lune";
stats.sectBenefic = isDayChart ? "Jupiter" : "Vénus";
stats.sectMalefic = isDayChart ? "Saturne" : "Mars";
stats.contraSectMalefic = isDayChart ? "Mars" : "Saturne";

// Triplicité — seigneurs diurne/nocturne (Ptolémée/Dorothée), utilisé par locataires + Almutem
const TRIPLIC_DAY_EARLY = {
    "Bélier":"Soleil","Lion":"Soleil","Sagittaire":"Soleil",
    "Taureau":"Vénus","Vierge":"Vénus","Capricorne":"Vénus",
    "Gémeaux":"Saturne","Balance":"Saturne","Verseau":"Saturne",
    "Cancer":"Vénus","Scorpion":"Vénus","Poissons":"Vénus"
};
const TRIPLIC_NIGHT_EARLY = {
    "Bélier":"Jupiter","Lion":"Jupiter","Sagittaire":"Jupiter",
    "Taureau":"Lune","Vierge":"Lune","Capricorne":"Lune",
    "Gémeaux":"Mercure","Balance":"Mercure","Verseau":"Mercure",
    "Cancer":"Mars","Scorpion":"Mars","Poissons":"Mars"
};
const TRIPLIC_PART_EARLY = {
    "Bélier":"Saturne","Lion":"Saturne","Sagittaire":"Saturne",
    "Taureau":"Mars","Vierge":"Mars","Capricorne":"Mars",
    "Gémeaux":"Jupiter","Balance":"Jupiter","Verseau":"Jupiter",
    "Cancer":"Lune","Scorpion":"Lune","Poissons":"Lune"
};
const getTriplicityRuler = (sign) => isDayChart ? (TRIPLIC_DAY_EARLY[sign] || null) : (TRIPLIC_NIGHT_EARLY[sign] || null);
const getTriplicityParticipant = (sign) => TRIPLIC_PART_EARLY[sign] || null;

if (asc && sun && moon) {
    // Part de Fortune : diurne = ASC + Lune - Soleil ; nocturne = inverse
    let pofDeg = isDayChart
        ? (asc.fullDegree + moon.fullDegree - sun.fullDegree)
        : (asc.fullDegree + sun.fullDegree  - moon.fullDegree);
    pofDeg = ((pofDeg % 360) + 360) % 360;
    planetes.push({ planet:{fr:"Part de Fortune",en:"Part of Fortune"}, fullDegree:pofDeg, normDegree:pofDeg%30, retroStr:"", isRetro:"False", zodiac_sign:{name:{fr:signs[Math.floor(pofDeg/30)].fr}} });

    // Lot de l'Esprit : inverse de Fortune
    let posDeg = isDayChart
        ? (asc.fullDegree + sun.fullDegree  - moon.fullDegree)
        : (asc.fullDegree + moon.fullDegree - sun.fullDegree);
    posDeg = ((posDeg % 360) + 360) % 360;
    planetes.push({ planet:{fr:"Lot de l'Esprit",en:"Lot of Spirit"}, fullDegree:posDeg, normDegree:posDeg%30, retroStr:"", isRetro:"False", zodiac_sign:{name:{fr:signs[Math.floor(posDeg/30)].fr}} });

    // Sprint 7 — Action 6 : Lots hermétiques supplémentaires
    const mars = planetes.find(p => p.planet.fr === "Mars");
    const venus = planetes.find(p => p.planet.fr === "Vénus");
    const jupiter = planetes.find(p => p.planet.fr === "Jupiter");
    const saturn = planetes.find(p => p.planet.fr === "Saturne");
    const mercury = planetes.find(p => p.planet.fr === "Mercure");

    const lotCalc = (a, b, c) => (((a + b - c) % 360) + 360) % 360;
    const lotCalcInverse = (a, b, c) => (((a + c - b) % 360) + 360) % 360;
    const pushLot = (frName, enName, deg) => {
        planetes.push({ planet:{fr:frName,en:enName}, fullDegree:deg, normDegree:deg%30, retroStr:"", isRetro:"False", zodiac_sign:{name:{fr:signs[Math.floor(deg/30)].fr}} });
    };

    // Lot de Nécessité (Ananke) : diurne = ASC + Fortune - Mercure ; nocturne = inverse
    if (mercury) {
        const necDeg = isDayChart ? lotCalc(asc.fullDegree, pofDeg, mercury.fullDegree) : lotCalcInverse(asc.fullDegree, pofDeg, mercury.fullDegree);
        pushLot("Lot de Nécessité", "Lot of Necessity", necDeg);
    }
    // Lot d'Éros : diurne = ASC + Vénus - Esprit ; nocturne = inverse
    if (venus) {
        const erosDeg = isDayChart ? lotCalc(asc.fullDegree, venus.fullDegree, posDeg) : lotCalcInverse(asc.fullDegree, venus.fullDegree, posDeg);
        pushLot("Lot d'Éros", "Lot of Eros", erosDeg);
    }
    // Lot de Courage (Tolma) : diurne = ASC + Fortune - Mars ; nocturne = inverse
    if (mars) {
        const courDeg = isDayChart ? lotCalc(asc.fullDegree, pofDeg, mars.fullDegree) : lotCalcInverse(asc.fullDegree, pofDeg, mars.fullDegree);
        pushLot("Lot de Courage", "Lot of Courage", courDeg);
    }
    // Lot de Némésis : diurne = ASC + Fortune - Saturne ; nocturne = inverse
    if (saturn) {
        const nemDeg = isDayChart ? lotCalc(asc.fullDegree, pofDeg, saturn.fullDegree) : lotCalcInverse(asc.fullDegree, pofDeg, saturn.fullDegree);
        pushLot("Lot de Némésis", "Lot of Nemesis", nemDeg);
    }
    // Lot de Basis : ASC + Fortune - Esprit (invariant sect)
    const basisDeg = lotCalc(asc.fullDegree, pofDeg, posDeg);
    pushLot("Lot de Basis", "Lot of Basis", basisDeg);

    // Lot d'Exaltation : ASC + (degré exalt Soleil 19°Bélier) - Soleil
    const exaltSunDeg = 19; // 19° Bélier
    const exaltDeg = lotCalc(asc.fullDegree, exaltSunDeg, sun.fullDegree);
    pushLot("Lot d'Exaltation", "Lot of Exaltation", exaltDeg);

    // Lot du Daemon : diurne = ASC + Soleil - Esprit ; nocturne = inverse
    const daemonDeg = isDayChart ? lotCalc(asc.fullDegree, sun.fullDegree, posDeg) : lotCalcInverse(asc.fullDegree, sun.fullDegree, posDeg);
    pushLot("Lot du Daemon", "Lot of Daemon", daemonDeg);

    // ── C7 : Parts Arabes élargies (Vettius Valens, Paulus Alexandrinus, Firmicus Maternus) ──
    // Lot de Victoire (Nikè) : diurne = ASC + Jupiter - Esprit ; nocturne = inverse
    if (jupiter) {
        const vicDeg = isDayChart ? lotCalc(asc.fullDegree, jupiter.fullDegree, posDeg) : lotCalcInverse(asc.fullDegree, jupiter.fullDegree, posDeg);
        pushLot("Lot de Victoire", "Lot of Victory", vicDeg);
    }
    // Lot du Père : diurne = ASC + Saturne - Soleil ; nocturne = inverse
    if (saturn) {
        const pereDeg = isDayChart ? lotCalc(asc.fullDegree, saturn.fullDegree, sun.fullDegree) : lotCalcInverse(asc.fullDegree, saturn.fullDegree, sun.fullDegree);
        pushLot("Lot du Père", "Lot of Father", pereDeg);
    }
    // Lot de la Mère : diurne = ASC + Lune - Vénus ; nocturne = inverse
    if (venus) {
        const mereDeg = isDayChart ? lotCalc(asc.fullDegree, moon.fullDegree, venus.fullDegree) : lotCalcInverse(asc.fullDegree, moon.fullDegree, venus.fullDegree);
        pushLot("Lot de la Mère", "Lot of Mother", mereDeg);
    }
    // Lot de Maladie (Valens) : diurne = ASC + Mars - Saturne ; nocturne = inverse
    if (mars && saturn) {
        const malDeg = isDayChart ? lotCalc(asc.fullDegree, mars.fullDegree, saturn.fullDegree) : lotCalcInverse(asc.fullDegree, mars.fullDegree, saturn.fullDegree);
        pushLot("Lot de Maladie", "Lot of Illness", malDeg);
    }
    // Lot du Mariage : diurne = ASC + DSC - Vénus ; nocturne = inverse (formule universelle Valens)
    const dsc = maisons.find(m => m.House === 7);
    if (venus && dsc) {
        const mariDeg = isDayChart ? lotCalc(asc.fullDegree, dsc.degree, venus.fullDegree) : lotCalcInverse(asc.fullDegree, dsc.degree, venus.fullDegree);
        pushLot("Lot du Mariage", "Lot of Marriage", mariDeg);
    }
    // Lot des Enfants (Valens) : diurne = ASC + Jupiter - Saturne ; nocturne = inverse
    if (jupiter && saturn) {
        const enfDeg = isDayChart ? lotCalc(asc.fullDegree, jupiter.fullDegree, saturn.fullDegree) : lotCalcInverse(asc.fullDegree, jupiter.fullDegree, saturn.fullDegree);
        pushLot("Lot des Enfants", "Lot of Children", enfDeg);
    }
    // Lot de Voyage (Firmicus) : diurne = ASC + Mars - Saturne renversé pour cette formule ≠ maladie
    // → Firmicus : ASC + 9e cuspide - maître du 9e ; simplifié → ASC + Saturne - Jupiter (éloignement)
    if (jupiter && saturn) {
        const voyDeg = isDayChart ? lotCalc(asc.fullDegree, saturn.fullDegree, jupiter.fullDegree) : lotCalcInverse(asc.fullDegree, saturn.fullDegree, jupiter.fullDegree);
        pushLot("Lot de Voyage", "Lot of Travel", voyDeg);
    }
}

let nn = planetes.find(p => p.planet.fr === "Nœud Nord");
if (nn) {
    let sd = (nn.fullDegree + 180) % 360;
    const sudDecl = typeof nn.declinaison === 'number' ? -nn.declinaison : undefined;
    planetes.push({ planet:{fr:"Nœud Sud",en:"South Node"}, fullDegree:sd, normDegree:sd%30, retroStr:nn.retroStr, isRetro:nn.isRetro, zodiac_sign:{name:{fr:signs[Math.floor(sd/30)].fr}}, declinaison:sudDecl });
}

// 5. ASPECTS MAJEURS + MINEURS
const aspectTypes = [
    {name:"Conjonction", deg:0,   orb:10, nodalOrb:8, smallOrb:8,  major:true},
    {name:"Sextile",     deg:60,  orb:6,  nodalOrb:5, smallOrb:3,  major:true},
    {name:"Carré",       deg:90,  orb:8,  nodalOrb:7, smallOrb:4,  major:true},
    {name:"Trigone",     deg:120, orb:8,  nodalOrb:7, smallOrb:4,  major:true},
    {name:"Opposition",  deg:180, orb:10, nodalOrb:8, smallOrb:6,  major:true},
    {name:"Quinconce",   deg:150, orb:3,  nodalOrb:2, smallOrb:2,  major:false},
    {name:"Semi-Sextile",deg:30,  orb:2,  nodalOrb:1, smallOrb:1,  major:false},
    {name:"Semi-Carré",  deg:45,  orb:2,  nodalOrb:2, smallOrb:1,  major:false},
    {name:"Quintile",    deg:72,  orb:2,  nodalOrb:2, smallOrb:1,  major:false},
    {name:"Biquintile",  deg:144, orb:2,  nodalOrb:1, smallOrb:1,  major:false},
    {name:"Sesqui-Carré",deg:135, orb:2,  nodalOrb:2, smallOrb:1,  major:false}
];
const smallBodies  = ["Chiron","Vesta","Cérès","Ceres","Pallas","Junon","Juno","Lilith"];
const nodalBodies  = ["Nœud Nord","Nœud Sud","Part de Fortune","Part of Fortune","Lot de l'Esprit","Lot of Spirit","Lot de Nécessité","Lot of Necessity","Lot d'Éros","Lot of Eros","Lot de Courage","Lot of Courage","Lot de Némésis","Lot of Nemesis","Lot de Basis","Lot of Basis","Lot d'Exaltation","Lot of Exaltation","Lot du Daemon","Lot of Daemon"];

// Facteur d'orbe planète-spécifique (Solar Fire standard)
const PLANET_ORB_FACTOR = {
    "Soleil":1.0, "Lune":1.0, "Ascendant":1.0, "Milieu du Ciel":1.0,
    "Descendant":1.0, "Imum Coeli":1.0,
    "Mercure":0.75, "Vénus":0.75, "Mars":0.75,
    "Jupiter":0.65, "Saturne":0.65,
    "Uranus":0.55, "Neptune":0.55, "Pluton":0.55,
    "Chiron":0.55, "Nœud Nord":0.6, "Nœud Sud":0.6
};

const AXIS_PAIRS = [
    new Set(["Milieu du Ciel", "Imum Coeli"]),
    new Set(["Ascendant", "Descendant"]),
    new Set(["Nœud Nord", "Nœud Sud"])
];
const isAxisPair = (n1, n2) => AXIS_PAIRS.some(pair => pair.has(n1) && pair.has(n2));

let aspects = [];
for(let i=0; i<planetes.length; i++) {
    for(let j=i+1; j<planetes.length; j++) {
        let p1=planetes[i], p2=planetes[j];
        let name1 = p1.planet.fr || p1.planet.en;
        let name2 = p2.planet.fr || p2.planet.en;
        if (isAxisPair(name1, name2)) continue;
        let isSmall  = smallBodies.includes(name1) || smallBodies.includes(name2);
        let isNodal  = nodalBodies.includes(name1) || nodalBodies.includes(name2);
        let activeType = isSmall ? "smallOrb" : (isNodal ? "nodalOrb" : "orb");
        const f1 = PLANET_ORB_FACTOR[name1] ?? 0.5;
        const f2 = PLANET_ORB_FACTOR[name2] ?? 0.5;
        const orbModulator = Math.max(f1, f2);
        let diff = Math.abs(p1.fullDegree - p2.fullDegree);
        if(diff > 180) diff = 360 - diff;
        aspectTypes.forEach(a => {
            let activeOrb  = a[activeType] * orbModulator;
            let exactitude = Math.abs(diff - a.deg);
            if(exactitude <= activeOrb) {
                aspects.push({ p1:name1, p2:name2, aspect:a.name, exactitude:exactitude.toFixed(2), isMajor:a.major });
            }
        });
    }
}

// Fonctions d'affichage des aspects — utilisent les scores calculés en bloc 6k
// (appelées en bloc 7+ quand les aspects sont déjà enrichis, triés et flaggés isPromoted)

// ── Sprint 6 — Module A : Qualificatif d'orbe calculé ──
const orbQualifier = (orb) => {
    const o = typeof orb === "string" ? parseFloat(orb) : orb;
    if (o < 1)   return "exact";
    if (o < 3)   return "serré";
    if (o < 5)   return "moyen";
    return "large";
};

// ── Sprint 6 — Module B1+E2 : Natures planétaires ──
const PLANET_NATURES = {
    "Soleil":"luminaire","Lune":"luminaire",
    "Mercure":"neutre","Vénus":"bénéfique","Mars":"maléfique",
    "Jupiter":"bénéfique","Saturne":"maléfique",
    "Uranus":"maléfique","Neptune":"dissolvant","Pluton":"maléfique",
    "Chiron":"neutre","Nœud Nord":"neutre","Nœud Sud":"neutre",
    "Lilith":"maléfique","Cérès":"neutre","Ceres":"neutre",
    "Junon":"neutre","Juno":"neutre","Vesta":"neutre","Pallas":"neutre",
    "Ascendant":"neutre","Milieu du Ciel":"neutre","Descendant":"neutre","Imum Coeli":"neutre"
};

const getNatureTag = (p1, p2) => {
    const n1 = PLANET_NATURES[p1], n2 = PLANET_NATURES[p2];
    if (!n1 || !n2 || n1 === "neutre" && n2 === "neutre") return "";
    if (n1 === "dissolvant" || n2 === "dissolvant") {
        const otherN = n1 === "dissolvant" ? n2 : n1;
        if (otherN === "maléfique")  return " [Nature: dissolution de la tension — transcendance possible mais risque de confusion]";
        if (otherN === "bénéfique")  return " [Nature: sublimation — inspiration élevée mais risque d'idéalisation]";
        if (otherN === "luminaire")  return " [Nature: voile sur le luminaire — intuition amplifiée mais identité potentiellement floue]";
        return "";
    }
    if (n1 === "bénéfique" && n2 === "bénéfique")  return " [Nature: synergie bénéfique — énergies qui s'emboîtent harmonieusement]";
    if (n1 === "maléfique" && n2 === "maléfique")  return " [Nature: friction maléfique — tension intensifiée, potentiel d'obstacle]";
    if ((n1==="bénéfique"&&n2==="maléfique")||(n1==="maléfique"&&n2==="bénéfique"))
        return " [Nature: mixte — le bénéfique tempère le maléfique, mais sous tension]";
    if (n1 === "luminaire" || n2 === "luminaire") {
        const otherN = n1 === "luminaire" ? n2 : n1;
        if (otherN === "bénéfique")  return " [Nature: luminaire + bénéfique — vitalité amplifiée et soutenue]";
        if (otherN === "maléfique")  return " [Nature: luminaire + maléfique — vitalité mise au défi]";
        if (otherN === "dissolvant") return " [Nature: voile sur le luminaire — intuition amplifiée mais identité potentiellement floue]";
    }
    return "";
};

// ── Sprint 6 — Module E1 : Appliquant / Séparant (aspects nataux) ──
const PLANET_SPEED_RANK = {
    "Lune":1,"Mercure":2,"Vénus":3,"Soleil":4,"Mars":5,
    "Jupiter":6,"Saturne":7,"Uranus":8,"Neptune":9,"Pluton":10,
    "Chiron":7.5,"Lilith":4.5,"Cérès":5.5,"Ceres":5.5,"Junon":5.2,"Juno":5.2,"Vesta":5.3,"Pallas":5.4,
    "Nœud Nord":7.2,"Nœud Sud":7.2
};
const getAppSepTag = (pFaster, pSlower, aspDeg, exactitude) => {
    const r1 = PLANET_SPEED_RANK[pFaster], r2 = PLANET_SPEED_RANK[pSlower];
    if (!r1 || !r2) return "";
    const fast = r1 < r2 ? pFaster : pSlower;
    const slow = r1 < r2 ? pSlower : pFaster;
    const pFast = planetes.find(p => p.planet.fr === fast);
    const pSlow = planetes.find(p => p.planet.fr === slow);
    if (!pFast || !pSlow) return "";
    const fastRetro = pFast.isRetro === "True" || pFast.isRetro === true;
    const diff = ((pFast.fullDegree - pSlow.fullDegree) + 360) % 360;
    let approaching, separating;
    if (aspDeg === 0) {
        approaching = diff > 180;
        separating  = diff <= 180 && diff > 0;
    } else {
        approaching = diff > aspDeg && diff < aspDeg + 15;
        separating  = diff < aspDeg || diff > aspDeg + 345;
    }
    if (fastRetro) {
        const tmp = approaching;
        approaching = separating;
        separating = tmp;
    }
    if (approaching) return " [appliquant]";
    if (separating)  return " [séparant]";
    return "";
};
const ASP_DEG_MAP = {"Conjonction":0,"Opposition":180,"Carré":90,"Trigone":120,"Sextile":60,"Quinconce":150,"Semi-Sextile":30,"Semi-Carré":45,"Quintile":72,"Biquintile":144,"Sesqui-Carré":135};

const MINOR_ASPECT_MEANINGS = {
    "Quintile":     "harmonie créatrice, don structurel",
    "Biquintile":   "harmonie créatrice avancée, talent latent",
    "Semi-Sextile": "irritant mineur, ajustement progressif entre signes adjacents",
    "Semi-Carré":   "friction légère, micro-tension de développement",
    "Sesqui-Carré": "tension de friction constructive",
    "Quinconce":    "ajustement obligatoire, tension inconsciente"
};

const getMajorAspectsStr = (pName) => {
    let asps = aspects.filter(a => a.isMajor && (a.p1===pName || a.p2===pName));
    if (!asps.length) return "Aucun aspect majeur";
    return asps.map(a => {
        const partner = a.p1===pName ? a.p2 : a.p1;
        const prefix  = a.prioriteEmoji ? `${a.prioriteEmoji} ${a.prioriteLabel} — ` : "";
        const oq = orbQualifier(a.exactitude);
        const nt = getNatureTag(pName, partner);
        const aspDeg = ASP_DEG_MAP[a.aspect] ?? 0;
        const appSep = getAppSepTag(a.p1, a.p2, aspDeg, parseFloat(a.exactitude));
        return `${prefix}${a.aspect} avec ${partner} (${a.exactitude}° — ${oq})${appSep}${nt}`;
    }).join(" | ");
};

// Aspects mineurs promus (score ≥ seuil Option B) — traités comme des aspects majeurs par le LLM
const getPromotedMinorAspectsStr = (pName) => {
    let asps = aspects.filter(a => !a.isMajor && a.isPromoted && (a.p1===pName || a.p2===pName));
    if (!asps.length) return null;
    return asps.map(a => {
        const partner  = a.p1===pName ? a.p2 : a.p1;
        const meaning  = MINOR_ASPECT_MEANINGS[a.aspect] ? ` — nature : ${MINOR_ASPECT_MEANINGS[a.aspect]}` : "";
        const oq = orbQualifier(a.exactitude);
        const nt = getNatureTag(pName, partner);
        const aspDeg = ASP_DEG_MAP[a.aspect] ?? 0;
        const appSep = getAppSepTag(a.p1, a.p2, aspDeg, parseFloat(a.exactitude));
        return `   ${a.prioriteEmoji} ${a.prioriteLabel} — ${a.aspect} avec ${partner} (${a.exactitude}° — ${oq})${appSep}${meaning}${nt}`;
    }).join("\n");
};

// Aspects mineurs non promus (tous les autres aspects mineurs)
const getMinorAspectsStr = (pName) => {
    let asps = aspects.filter(a => !a.isMajor && !a.isPromoted && (a.p1===pName || a.p2===pName))
        .sort((a,b) => parseFloat(a.exactitude) - parseFloat(b.exactitude)).slice(0, 5);
    if (!asps.length) return null;
    return asps.map(a => {
        const partner = a.p1===pName ? a.p2 : a.p1;
        const prefix  = a.prioriteEmoji ? `${a.prioriteEmoji} ${a.prioriteLabel} — ` : "";
        return `${prefix}${a.aspect} avec ${partner} (${a.exactitude}°)`;
    }).join(" | ");
};

// ─────────────────────────────────────────────────────────────────
// 6. NOUVELLES TECHNIQUES
// ─────────────────────────────────────────────────────────────────

// 6a. CONDITIONS HÉLIOCENTRIQUES (Cazimi / Combuste / Sous les rayons / Oriental / Occidental)
const helioConditions = {};
if (sun) {
    const inferiorPlanets  = ["Mercure","Vénus"];
    const helioTargets     = ["Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron"];
    planetes.forEach(p => {
        let name = p.planet.fr || p.planet.en;
        if (!helioTargets.includes(name)) return;
        let diff = p.fullDegree - sun.fullDegree;
        while (diff >  180) diff -= 360;
        while (diff < -180) diff += 360;
        let absDiff = Math.abs(diff);
        let condition = null;
        const isLune = name === "Lune";
        if (absDiff <= 0.283)   condition = isLune
            ? "CAZIMI LUNAIRE — Nouvelle Lune exacte au cœur du Soleil (fusion lumière/émotion, puissance exceptionnelle)"
            : "CAZIMI — au cœur du Soleil (force exceptionnelle)";
        else if (absDiff <= 8)  condition = isLune
            ? `NOUVELLE LUNE (conjonction Soleil-Lune à ${absDiff.toFixed(1)}°) — phase d'ensemencement, intériorisation émotionnelle intense, énergie tournée vers le subconscient`
            : `COMBUSTE — brûlé par le Soleil à ${absDiff.toFixed(1)}° (affaibli, principe planétaire neutralisé)`;
        else if (absDiff <= 15) condition = isLune
            ? (diff > 0
                ? `LUNE CROISSANT (${absDiff.toFixed(1)}° après le Soleil) — début de cycle, émergence émotionnelle progressive, volonté d'action instinctive`
                : `LUNE BALSAMIQUE (${absDiff.toFixed(1)}° avant le Soleil) — fin de cycle, introspection profonde, lâcher-prise et sagesse distillée`)
            : `SOUS LES RAYONS — à ${absDiff.toFixed(1)}° du Soleil (diminué, agit en coulisse)`;

        let orientation = null;
        if (inferiorPlanets.includes(name)) {
            if (absDiff <= 15) {
                orientation = diff < 0 ? "Oriental — étoile du matin (se lève avant le Soleil)" : "Occidental — étoile du soir (se couche après le Soleil)";
            } else {
                orientation = diff < 0 ? "Oriental (élongation Ouest, étoile du matin)" : "Occidental (élongation Est, étoile du soir)";
            }
        }
        if (condition || orientation) helioConditions[name] = { condition, orientation };
    });
}

// 6a-bis. PLANÈTES STATIONNAIRES (vitesse quotidienne quasi-nulle)
// Seuils en °/jour — sous ce seuil, la planète est considérée stationnaire
const STATION_THRESHOLDS = {
    "Mercure": 0.3, "Vénus": 0.15, "Mars": 0.08,
    "Jupiter": 0.02, "Saturne": 0.01, "Uranus": 0.005,
    "Neptune": 0.003, "Pluton": 0.002, "Chiron": 0.01
};
const stationaryPlanets = [];
Object.keys(STATION_THRESHOLDS).forEach(name => {
    const p = planetes.find(x => (x.planet.fr || x.planet.en) === name);
    if (!p) return;
    const speed = p.vitesse_longitude ?? p.speed ?? p.daily_motion ?? null;
    if (speed === null || speed === undefined) return;
    const absSpeed = Math.abs(parseFloat(speed));
    const threshold = STATION_THRESHOLDS[name];
    if (absSpeed <= threshold) {
        const isRetro = p.retroStr || (p.isRetro === "True" || p.isRetro === true);
        const direction = isRetro ? "Station Rétrograde (SR)" : "Station Directe (SD)";
        stationaryPlanets.push({
            planet: name, speed: absSpeed.toFixed(4), threshold,
            direction, house: getHouseNumber(p.fullDegree),
            sign: p.zodiac_sign?.name?.fr
        });
    }
});

// 6b. PLANÈTES ANGULAIRES (within 5° of ASC / DSC / MC / IC)
const angleNames    = ["Ascendant","Descendant","Milieu du Ciel","Imum Coeli"];
const corePlanets   = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron"];
const angularPlanets = [];
corePlanets.forEach(name => {
    let p = planetes.find(x => x.planet.fr === name); if (!p) return;
    angleNames.forEach(angleName => {
        let angleP = planetes.find(a => a.planet.fr === angleName); if (!angleP) return;
        let diff = angularDiff(p.fullDegree, angleP.fullDegree);
        if (diff <= 5) angularPlanets.push({ planet:name, angle:angleName, orb:diff.toFixed(2), house:getHouseNumber(p.fullDegree), sign:p.zodiac_sign?.name?.fr });
    });
});

// 6c. DEGRÉS CRITIQUES (29° Anarète, 0° Ingress, degrés critiques par modalité)
const criticalDegConfig = { cardinal:[0,13,26], fixed:[8,9,21,22], mutable:[4,17] };
const cardinalSigns = ["Bélier","Cancer","Balance","Capricorne"];
const fixedSigns    = ["Taureau","Lion","Scorpion","Verseau"];
const mutableSigns  = ["Gémeaux","Vierge","Sagittaire","Poissons"];
const criticalPlanets = [];
corePlanets.forEach(name => {
    let p = planetes.find(x => x.planet.fr === name); if (!p) return;
    let deg  = p.normDegree;
    let sign = p.zodiac_sign?.name?.fr;
    let flags = [];
    if (deg >= 29)    flags.push("29° Anarète — degré de fin de cycle, tension et urgence");
    if (deg < 1)      flags.push("0° Ingress — énergie brute non encore filtrée, commencement absolu");
    if (cardinalSigns.includes(sign)) criticalDegConfig.cardinal.forEach(cd => { if (Math.abs(deg-cd) < 1) flags.push(`Degré critique cardinal ${cd}° (crise et tournant)`); });
    if (fixedSigns.includes(sign))    criticalDegConfig.fixed.forEach(cd   => { if (Math.abs(deg-cd) < 1) flags.push(`Degré critique fixe ${cd}° (tension accumulée)`); });
    if (mutableSigns.includes(sign))  criticalDegConfig.mutable.forEach(cd => { if (Math.abs(deg-cd) < 1) flags.push(`Degré critique mutable ${cd}° (carrefour de choix)`); });
    if (flags.length > 0) criticalPlanets.push({ planet:name, sign, degree:deg.toFixed(2), flags });
});

// 6d. RÉCEPTIONS MUTUELLES
const receptionPlanets  = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
const mutualReceptions  = [];
for (let i=0; i<receptionPlanets.length; i++) {
    for (let j=i+1; j<receptionPlanets.length; j++) {
        let nA=receptionPlanets[i], nB=receptionPlanets[j];
        let pA=planetes.find(p=>p.planet.fr===nA), pB=planetes.find(p=>p.planet.fr===nB);
        if (!pA || !pB) continue;
        let sA=pA.zodiac_sign?.name?.fr, sB=pB.zodiac_sign?.name?.fr;
        let aInBDom = dignities[nA] && dignities[nB]?.dom?.includes(sA);
        let bInADom = dignities[nB] && dignities[nA]?.dom?.includes(sB);
        if (aInBDom && bInADom) {
            mutualReceptions.push({ p1:nA, sign1:sA, house1:getHouseNumber(pA.fullDegree), p2:nB, sign2:sB, house2:getHouseNumber(pB.fullDegree), type:"domicile" });
        }
        let aInBExa = dignities[nA] && dignities[nB]?.exa?.includes(sA);
        let bInAExa = dignities[nB] && dignities[nA]?.exa?.includes(sB);
        if (aInBExa && bInAExa && !(aInBDom && bInADom)) {
            mutualReceptions.push({ p1:nA, sign1:sA, house1:getHouseNumber(pA.fullDegree), p2:nB, sign2:sB, house2:getHouseNumber(pB.fullDegree), type:"exaltation" });
        }
        // Réception mixte : A en domicile de B + B en exaltation de A (ou inverse)
        if (!(aInBDom && bInADom) && !(aInBExa && bInAExa)) {
            if ((aInBDom && bInAExa) || (aInBExa && bInADom)) {
                mutualReceptions.push({ p1:nA, sign1:sA, house1:getHouseNumber(pA.fullDegree), p2:nB, sign2:sB, house2:getHouseNumber(pB.fullDegree), type:"mixte" });
            }
        }
    }
}

// 6e. CONFIGURATIONS NATALES (Stellium, Grand Trigone, T-Carré, Grand Carré, Yod, Cerf-Volant)
// confPlanets inclut les 10 planètes + Chiron + les 4 Angles (ASC, MC, DSC, IC).
// Les Angles sont construits depuis les maisons si absents du payload API.
// Sans cette extension, le bonus +40 "Si Angle impliqué" serait du code mort
// et des configurations majeures (ex: T-Carré avec l'ASC comme apex) seraient manquées.
const CONF_ANGLES_SET = new Set(["Ascendant","Milieu du Ciel","Descendant","Imum Coeli"]);
const confPlanetsBase = planetes.filter(p => corePlanets.includes(p.planet.fr || p.planet.en));
const angleObjectsConf = ["Ascendant","Milieu du Ciel","Descendant","Imum Coeli"].map(angleName => {
    let existing = planetes.find(p => p.planet.fr === angleName);
    if (existing) return existing;
    const houseNum = angleName === "Descendant" ? 7 : angleName === "Imum Coeli" ? 4 : null;
    if (!houseNum) return null;
    const m = maisons.find(m => m.House === houseNum);
    if (!m) return null;
    return { planet:{fr:angleName,en:angleName}, fullDegree:m.degree, normDegree:m.degree%30, retroStr:"", isRetro:"False", zodiac_sign:{name:{fr:signs[Math.floor(m.degree/30)%12].fr}} };
}).filter(Boolean);
const confPlanets = [...confPlanetsBase];
angleObjectsConf.forEach(ao => {
    const aoName = ao.planet.fr || ao.planet.en;
    if (!confPlanets.find(p => (p.planet.fr || p.planet.en) === aoName)) confPlanets.push(ao);
});
const configurations = [];

// Stellium : 3+ planètes dans le même signe
let signGroups = {};
confPlanets.forEach(p => {
    let sign = p.zodiac_sign?.name?.fr;
    if (!signGroups[sign]) signGroups[sign] = [];
    signGroups[sign].push(p.planet.fr || p.planet.en);
});
Object.entries(signGroups).forEach(([sign, pList]) => {
    if (pList.length >= 3 && pList.filter(p => CONF_ANGLES_SET.has(p)).length < 3) {
        configurations.push({ type:"Stellium", planets:pList, description:`${pList.join(", ")} regroupés en ${sign} — concentration d'énergie ${sign} très intense` });
    }
});

// Stellium par Maison : 3+ planètes dans la même maison (complémentaire du Stellium par signe)
// Pertinent quand un Stellium s'étale sur deux signes dans une maison large ou interceptée.
const houseGroupsStellium = {};
confPlanets.forEach(p => {
    const house = getHouseNumber(p.fullDegree);
    if (!houseGroupsStellium[house]) houseGroupsStellium[house] = [];
    const pName = p.planet.fr || p.planet.en;
    if (!houseGroupsStellium[house].includes(pName)) houseGroupsStellium[house].push(pName);
});
Object.entries(houseGroupsStellium).forEach(([house, pList]) => {
    if (pList.length >= 3) {
        const alreadyCovered = configurations.some(c =>
            c.type === "Stellium" && c.planets.length === pList.length && c.planets.every(p => pList.includes(p))
        );
        if (!alreadyCovered && pList.filter(p => CONF_ANGLES_SET.has(p)).length < 3) {
            configurations.push({ type:"Stellium", planets:pList, description:`${pList.join(", ")} concentrés en Maison ${house} — Stellium de maison, thématiques de M${house} hyper-activées` });
        }
    }
});

// Grand Trigone : 3 planètes à ~120° (orbe 8°)
const grandTrigoneSets = [];
for (let i=0; i<confPlanets.length; i++) {
    for (let j=i+1; j<confPlanets.length; j++) {
        for (let k=j+1; k<confPlanets.length; k++) {
            let d12=angularDiff(confPlanets[i].fullDegree,confPlanets[j].fullDegree);
            let d23=angularDiff(confPlanets[j].fullDegree,confPlanets[k].fullDegree);
            let d13=angularDiff(confPlanets[i].fullDegree,confPlanets[k].fullDegree);
            if (Math.abs(d12-120)<=8 && Math.abs(d23-120)<=8 && Math.abs(d13-120)<=8) {
                let n1=confPlanets[i].planet.fr, n2=confPlanets[j].planet.fr, n3=confPlanets[k].planet.fr;
                grandTrigoneSets.push([n1,n2,n3]);
                configurations.push({ type:"Grand Trigone", planets:[n1,n2,n3], description:`${n1} — ${n2} — ${n3} : grande harmonie et facilité, risque d'inertie sans effort conscient` });
            }
        }
    }
}

// T-Carré : 2 planètes en opposition + une troisième en carré aux deux
let tcarreKeys = new Set();
for (let i=0; i<confPlanets.length; i++) {
    for (let j=i+1; j<confPlanets.length; j++) {
        if (Math.abs(angularDiff(confPlanets[i].fullDegree,confPlanets[j].fullDegree)-180)>10) continue;
        for (let k=0; k<confPlanets.length; k++) {
            if (k===i||k===j) continue;
            let dik=angularDiff(confPlanets[i].fullDegree,confPlanets[k].fullDegree);
            let djk=angularDiff(confPlanets[j].fullDegree,confPlanets[k].fullDegree);
            if (Math.abs(dik-90)<=8 && Math.abs(djk-90)<=8) {
                let n1=confPlanets[i].planet.fr, n2=confPlanets[j].planet.fr, nk=confPlanets[k].planet.fr;
                let key=[n1,n2,nk].sort().join("|");
                if (!tcarreKeys.has(key) && !isAxisPair(n1, n2) && ![n1,n2,nk].every(n => CONF_ANGLES_SET.has(n))) {
                    tcarreKeys.add(key);
                    configurations.push({ type:"T-Carré", planets:[n1,n2,nk], description:`${n1} opposition ${n2}, tous deux en carré à ${nk} (apex) — tension persistante, moteur de dépassement de soi` });
                }
            }
        }
    }
}

// Grand Carré : 4 planètes en carré/opposition mutuels
let grandcarreKeys = new Set();
for (let i=0; i<confPlanets.length; i++) for (let j=i+1; j<confPlanets.length; j++) for (let k=j+1; k<confPlanets.length; k++) for (let l=k+1; l<confPlanets.length; l++) {
    let ps=[confPlanets[i],confPlanets[j],confPlanets[k],confPlanets[l]];
    let sorted=[...ps].sort((a,b)=>a.fullDegree-b.fullDegree);
    let d01=angularDiff(sorted[0].fullDegree,sorted[1].fullDegree);
    let d12=angularDiff(sorted[1].fullDegree,sorted[2].fullDegree);
    let d23=angularDiff(sorted[2].fullDegree,sorted[3].fullDegree);
    let d30=angularDiff(sorted[3].fullDegree,sorted[0].fullDegree);
    if ([d01,d12,d23,d30].every(d=>Math.abs(d-90)<=10)) {
        let names=ps.map(p=>p.planet.fr); let key=names.slice().sort().join("|");
        if (!grandcarreKeys.has(key) && names.filter(n => CONF_ANGLES_SET.has(n)).length < 3) {
            grandcarreKeys.add(key);
            configurations.push({ type:"Grand Carré", planets:names, description:`${names.join(", ")} : tension quadrilatérale maximale, défi de vie structurant et formateur` });
        }
    }
}

// Yod : 2 planètes en sextile, toutes deux en quinconce à un apex
// Sprint 8.3 — orbes resserrés au standard Robert Hand / Karen Hamaker-Zondag :
//   sextile ±3° (vs ±6° avant), quinconce ±2° (vs ±3° avant).
//   Justification : le Yod est une figure considérée comme rare ("mission karmique"),
//   les orbes laxistes du sextile global (±6°) produisaient ~50 Yods/100 cas dans
//   le bench v8.0/v8.2 (vs prévalence astrologique attendue 5-10 %).
//   Standard Hand/Hamaker-Zondag → ~21 Yods/100 cas, alignement astro.
let yodKeys = new Set();
for (let i=0; i<confPlanets.length; i++) {
    for (let j=i+1; j<confPlanets.length; j++) {
        if (Math.abs(angularDiff(confPlanets[i].fullDegree,confPlanets[j].fullDegree)-60)>3) continue;
        for (let k=0; k<confPlanets.length; k++) {
            if (k===i||k===j) continue;
            let dik=angularDiff(confPlanets[i].fullDegree,confPlanets[k].fullDegree);
            let djk=angularDiff(confPlanets[j].fullDegree,confPlanets[k].fullDegree);
            if (Math.abs(dik-150)<=2 && Math.abs(djk-150)<=2) {
                let n1=confPlanets[i].planet.fr, n2=confPlanets[j].planet.fr, nk=confPlanets[k].planet.fr;
                let key=[n1,n2,nk].sort().join("|");
                if (!yodKeys.has(key)) {
                    yodKeys.add(key);
                    configurations.push({ type:"Yod — Doigt de Dieu", planets:[n1,n2,nk], description:`${n1} sextile ${n2}, tous deux en quinconce à ${nk} (apex) — mission de vie, ajustement karmique obligatoire` });
                }
            }
        }
    }
}

// Cerf-Volant (Kite) : Grand Trigone + opposition + 2 sextiles depuis un 4e point
let kiteKeys = new Set();
grandTrigoneSets.forEach(([n1,n2,n3]) => {
    confPlanets.forEach(p => {
        let pk=p.planet.fr; if ([n1,n2,n3].includes(pk)) return;
        let triPs = [n1,n2,n3].map(tn => confPlanets.find(x=>(x.planet.fr||x.planet.en)===tn)).filter(Boolean);
        let oppIdx = triPs.findIndex(tp => Math.abs(angularDiff(p.fullDegree,tp.fullDegree)-180)<=8);
        if (oppIdx === -1) return;
        let sextileCount = triPs.filter((tp,idx) => idx!==oppIdx && Math.abs(angularDiff(p.fullDegree,tp.fullDegree)-60)<=6).length;
        if (sextileCount >= 2) {
            let key=[n1,n2,n3,pk].sort().join("|");
            if (!kiteKeys.has(key)) {
                kiteKeys.add(key);
                configurations.push({ type:"Cerf-Volant (Kite)", planets:[n1,n2,n3,pk], description:`Grand Trigone ${n1}-${n2}-${n3} avec ${pk} en opposition à ${triPs[oppIdx].planet.fr} — talent exceptionnel canalisé, potentiel actionnable` });
            }
        }
    });
});

// 6e-bis. CROIX MODALE (Cardinale / Fixe / Mutable)
// 4+ planètes dans les 4 signes d'un même mode, reliées par des oppositions et carrés
const MODE_SIGNS = {
    "Cardinal": ["Bélier","Cancer","Balance","Capricorne"],
    "Fixe":     ["Taureau","Lion","Scorpion","Verseau"],
    "Mutable":  ["Gémeaux","Vierge","Sagittaire","Poissons"]
};
const crossKeys = new Set();
Object.entries(MODE_SIGNS).forEach(([modeName, mSigns]) => {
    const inMode = confPlanets.filter(p => mSigns.includes(p.zodiac_sign?.name?.fr));
    if (inMode.length < 4) return;
    const signsCovered = new Set(inMode.map(p => p.zodiac_sign?.name?.fr));
    if (signsCovered.size < 3) return;
    const names = inMode.map(p => p.planet.fr);
    let hasOpp = false, hasSq = false;
    for (let i = 0; i < inMode.length && (!hasOpp || !hasSq); i++) {
        for (let j = i+1; j < inMode.length; j++) {
            let diff = Math.abs(inMode[i].fullDegree - inMode[j].fullDegree);
            if (diff > 180) diff = 360 - diff;
            if (Math.abs(diff - 180) <= 10) hasOpp = true;
            if (Math.abs(diff - 90) <= 8) hasSq = true;
        }
    }
    if (hasOpp && hasSq) {
        const key = names.slice().sort().join("|");
        if (!crossKeys.has(key)) {
            crossKeys.add(key);
            const modeDesc = modeName === "Cardinal" ? "action, initiative, crise" : modeName === "Fixe" ? "persévérance, résistance au changement, endurance" : "adaptabilité, dispersion, versatilité";
            configurations.push({ type:`Croix ${modeName}`, planets:names, description:`${names.join(", ")} : axe ${modeName} activé (${modeDesc}) — dynamique de tension structurante sur le mode ${modeName}` });
        }
    }
});

// 6e-ter. RECTANGLE MYSTIQUE : 2 oppositions reliées par 2 sextiles et 2 trigones
let rectMystiqueKeys = new Set();
for (let i=0; i<confPlanets.length; i++) {
    for (let j=i+1; j<confPlanets.length; j++) {
        if (Math.abs(angularDiff(confPlanets[i].fullDegree,confPlanets[j].fullDegree)-180)>10) continue;
        for (let k=0; k<confPlanets.length; k++) {
            if (k===i||k===j) continue;
            for (let l=k+1; l<confPlanets.length; l++) {
                if (l===i||l===j) continue;
                if (Math.abs(angularDiff(confPlanets[k].fullDegree,confPlanets[l].fullDegree)-180)>10) continue;
                const ds = [
                    angularDiff(confPlanets[i].fullDegree,confPlanets[k].fullDegree),
                    angularDiff(confPlanets[i].fullDegree,confPlanets[l].fullDegree),
                    angularDiff(confPlanets[j].fullDegree,confPlanets[k].fullDegree),
                    angularDiff(confPlanets[j].fullDegree,confPlanets[l].fullDegree)
                ];
                const sextiles = ds.filter(d => Math.abs(d-60)<=6).length;
                const trigones = ds.filter(d => Math.abs(d-120)<=8).length;
                if (sextiles >= 2 && trigones >= 2) {
                    const names = [confPlanets[i],confPlanets[j],confPlanets[k],confPlanets[l]].map(p=>p.planet.fr);
                    const key = names.slice().sort().join("|");
                    if (!rectMystiqueKeys.has(key)) {
                        rectMystiqueKeys.add(key);
                        configurations.push({ type:"Rectangle Mystique", planets:names, description:`${names.join(", ")} : double opposition harmonisée par sextiles et trigones — talent de médiation, capacité à résoudre les paradoxes` });
                    }
                }
            }
        }
    }
}

// 6e-quater. GRAND SEXTILE (Étoile de David) : 6 planètes à ~60° l'une de l'autre
let grandSextileKeys = new Set();
if (confPlanets.length >= 6) {
    for (let i=0; i<confPlanets.length; i++) {
        const candidates = [confPlanets[i]];
        let lastDeg = confPlanets[i].fullDegree;
        const sorted = confPlanets.filter((_,idx)=>idx!==i).sort((a,b) => {
            const da = ((a.fullDegree - lastDeg + 360) % 360);
            const db = ((b.fullDegree - lastDeg + 360) % 360);
            return da - db;
        });
        for (const p of sorted) {
            const dFromLast = angularDiff(candidates[candidates.length-1].fullDegree, p.fullDegree);
            if (Math.abs(dFromLast - 60) <= 6) candidates.push(p);
            if (candidates.length === 6) break;
        }
        if (candidates.length === 6) {
            const dClose = angularDiff(candidates[5].fullDegree, candidates[0].fullDegree);
            if (Math.abs(dClose - 60) <= 6) {
                const names = candidates.map(p => p.planet.fr);
                const key = names.slice().sort().join("|");
                if (!grandSextileKeys.has(key)) {
                    grandSextileKeys.add(key);
                    configurations.push({ type:"Grand Sextile (Étoile de David)", planets:names, description:`${names.join(", ")} : hexagramme parfait — flux d'énergie circulaire, potentiel exceptionnel et multifacette (configuration extrêmement rare)` });
                }
            }
        }
    }
}

// 6e-sext. FORME DU THÈME (Jones Patterns)
const computeChartShape = () => {
    const core10 = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
    const pDegs = core10.map(n => ({ name: n, deg: planetes.find(p => p.planet.fr === n)?.fullDegree })).filter(pd => pd.deg !== undefined).sort((a,b) => a.deg - b.deg);
    const n = pDegs.length;
    if (n < 7) return { shape: "Indéterminé", description: "Pas assez de planètes pour classifier" };
    const gaps = [];
    for (let i = 0; i < n; i++) {
        gaps.push(((pDegs[(i+1) % n].deg - pDegs[i].deg) + 360) % 360);
    }
    const maxGap = Math.max(...gaps);
    const maxGapIdx = gaps.indexOf(maxGap);
    const minGap = Math.min(...gaps);
    const spread = 360 - maxGap;

    const findSingleton = () => {
        const sorted = gaps.map((g,i) => ({g,i})).sort((a,b) => b.g - a.g);
        const g1i = sorted[0].i, g2i = sorted[1].i;
        let setA = [], setB = [];
        let idx = (g1i + 1) % n;
        while (idx !== (g2i + 1) % n) { setA.push(pDegs[idx].name); idx = (idx + 1) % n; }
        idx = (g2i + 1) % n;
        while (idx !== (g1i + 1) % n) { setB.push(pDegs[idx].name); idx = (idx + 1) % n; }
        return setA.length <= setB.length ? setA : setB;
    };

    const findLeading = () => pDegs[(maxGapIdx + 1) % n].name;

    if (spread <= 120) return { shape: "Bundle (Paquet)", description: "Toutes les planètes concentrées dans 120° — spécialiste intensif, vision focalisée mais limitée" };
    if (spread <= 180) return { shape: "Bowl (Bol)", description: `Planètes dans 180° — une moitié du zodiaque est vide, orientation unilatérale et conscience d'un manque` };
    // Bucket strict (Sprint 8.2) : un singleton n'est valide que s'il regroupe 1 ou 2 planètes
    // contiguës ENCADRÉES par 2 gaps significatifs (≥ 60° chacun). Sinon → Locomotive.
    // Avant Sprint 8.2 : Bucket capturait à tort tout maxGap ∈ [60, 120], rendant Locomotive
    // mathématiquement inatteignable (50/100 cas Bucket dans le bench v8.0, 0 Locomotive).
    if (spread > 180 && maxGap >= 60 && maxGap <= 120) {
        const singleton = findSingleton();
        const sortedG = gaps.slice().sort((a, b) => b - a);
        const g2 = sortedG[1];
        const isStrictBucket = singleton.length >= 1 && singleton.length <= 2 && g2 >= 60;
        if (isStrictBucket) {
            const sName = singleton.join(" et ");
            return { shape: "Bucket (Seau)", description: `${sName} isolé${singleton.length > 1 ? "s" : ""} face au groupe — singleton qui focalise et canalise toute l'énergie`, singleton: sName };
        }
    }
    if (maxGap <= 40 && minGap >= 15) return { shape: "Splash (Éclaboussure)", description: "Planètes réparties dans tout le zodiaque — polyvalence, dispersion possible, touche-à-tout" };
    const largeGaps = gaps.filter(g => g >= 60);
    if (largeGaps.length === 2 && largeGaps.every(g => g <= 120)) return { shape: "Seesaw (Balançoire)", description: "Deux groupes de planètes opposés — dualité permanente, oscillation entre deux pôles de vie" };
    // Locomotive : grand vide de 60-120° (1/6 à 1/3 du zodiaque). Borne supérieure étendue
    // de 90° à 120° (Sprint 8.2) pour récupérer les cas qui sortent du Bucket strict.
    if (maxGap >= 60 && maxGap <= 120) {
        const leading = findLeading();
        return { shape: "Locomotive", description: `Grand vide de ${maxGap.toFixed(0)}° — élan puissant, ambition motrice. ${leading} en tête tire le train` };
    }
    if (spread > 250 && maxGap > 90) return { shape: "Splay (Éventail)", description: "Distribution irrégulière avec accents marqués — individualiste, talents particuliers, résistance au conformisme" };
    return { shape: "Splay (Éventail)", description: "Distribution irrégulière — profil individualiste et diversifié" };
};
const chartShape = computeChartShape();

// 6f. ANTISCIA & CONTRA-ANTISCIA (miroir axe 0°Cancer/0°Capricorne)
// antiscia_deg = (180 - fullDeg + 360) % 360
const ANTISCIA_ORB = 1.5;
const antisciaPlanets = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
const antiscia = [];
for (let i=0; i<antisciaPlanets.length; i++) {
    for (let j=i+1; j<antisciaPlanets.length; j++) {
        let pA=planetes.find(p=>p.planet.fr===antisciaPlanets[i]);
        let pB=planetes.find(p=>p.planet.fr===antisciaPlanets[j]);
        if (!pA||!pB) continue;
        let antisciaDegA      = (180 - pA.fullDegree + 360) % 360;
        let contraAntisciaDegA = (antisciaDegA + 180) % 360;
        let diffA = angularDiff(antisciaDegA, pB.fullDegree);
        let diffC = angularDiff(contraAntisciaDegA, pB.fullDegree);
        if (diffA <= ANTISCIA_ORB) antiscia.push({ p1:antisciaPlanets[i], p2:antisciaPlanets[j], type:"Antiscia",        orb:diffA.toFixed(2) });
        if (diffC <= ANTISCIA_ORB) antiscia.push({ p1:antisciaPlanets[i], p2:antisciaPlanets[j], type:"Contra-antiscia", orb:diffC.toFixed(2) });
    }
}

// 6g. MIDPOINTS (10 planètes majeures) + détection des activateurs
const midpointPlanets = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
const midpoints = {};
for (let i=0; i<midpointPlanets.length; i++) {
    for (let j=i+1; j<midpointPlanets.length; j++) {
        let pA=planetes.find(p=>p.planet.fr===midpointPlanets[i]);
        let pB=planetes.find(p=>p.planet.fr===midpointPlanets[j]);
        if (!pA||!pB) continue;
        let diff = pB.fullDegree - pA.fullDegree;
        if (diff < 0) diff += 360;
        if (diff > 180) diff -= 360;
        let mp = ((pA.fullDegree + diff/2) % 360 + 360) % 360;
        let mpFar = (mp + 180) % 360;
        midpoints[`${midpointPlanets[i]}/${midpointPlanets[j]}`] = {
            near: mp, far: mpFar,
            sign: signs[Math.floor(mp/30)].fr, deg: (mp%30).toFixed(1)
        };
    }
}
const midpointActivations = [];
Object.entries(midpoints).forEach(([key, mp]) => {
    let [mpP1, mpP2] = key.split("/");
    planetes.forEach(p => {
        let name = p.planet.fr || p.planet.en;
        if (name === mpP1 || name === mpP2) return;
        if (["Part de Fortune","Lot de l'Esprit","Nœud Sud","Lot de Nécessité","Lot d'Éros","Lot de Courage","Lot de Némésis","Lot de Basis","Lot d'Exaltation","Lot du Daemon"].includes(name)) return;
        let dNear = angularDiff(p.fullDegree, mp.near);
        let dFar  = angularDiff(p.fullDegree, mp.far);
        let best  = Math.min(dNear, dFar);
        if (best <= 1.5) {
            midpointActivations.push({ activator:name, midpoint:key, type:dNear<=dFar?"direct":"miroir", orb:best.toFixed(2) });
        }
    });
});

