// ─────────────────────────────────────────────────────────────────
// 6h-bis. PARANS D'ÉTOILES FIXES (méthode Brady — co-angularité)
// Un paran se forme quand une étoile est sur un angle (lever/coucher/culmination)
// au même moment qu'une planète est sur un angle, évalué par le RAMC commun.
// ─────────────────────────────────────────────────────────────────
const PARAN_ORB = 1.5;
const OBLIQUITY = 23.4393;
const DEG = Math.PI / 180;

const geoLat = parseFloat(perso.latitude) || 0;
const paranResults = [];

if (Math.abs(geoLat) > 0.1) {
    const tanPhi = Math.tan(geoLat * DEG);

    function hourAngle(dec) {
        const tanDec = Math.tan(dec * DEG);
        const cosH = -tanPhi * tanDec;
        if (cosH < -1 || cosH > 1) return null;
        return Math.acos(cosH) / DEG;
    }

    function bodyAngles(ra, dec) {
        const H = hourAngle(dec);
        const angles = [];
        angles.push({ type: "Culmination", ramc: ((ra % 360) + 360) % 360 });
        angles.push({ type: "Anti-culmination", ramc: ((ra + 180) % 360 + 360) % 360 });
        if (H !== null) {
            angles.push({ type: "Lever", ramc: ((ra - H) % 360 + 360) % 360 });
            angles.push({ type: "Coucher", ramc: ((ra + H) % 360 + 360) % 360 });
        }
        return angles;
    }

    function eclToEq(lon, lat) {
        const L = lon * DEG, B = (lat || 0) * DEG, E = OBLIQUITY * DEG;
        const ra = Math.atan2(Math.sin(L) * Math.cos(E) - Math.tan(B) * Math.sin(E), Math.cos(L));
        const dec = Math.asin(Math.sin(B) * Math.cos(E) + Math.cos(B) * Math.sin(E) * Math.sin(L));
        return { ra: ((ra / DEG) % 360 + 360) % 360, dec: dec / DEG };
    }

    const PARAN_PLANETS = new Set(["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton","Chiron","Ascendant","Milieu du Ciel","Descendant","Imum Coeli"]);

    const planetAnglesMap = [];
    pointsEtoiles.forEach(p => {
        const pName = p.planet.fr || p.planet.en;
        if (!PARAN_PLANETS.has(pName)) return;
        if (LOTS_MATHEMATIQUES.has(pName)) return;
        let pRa, pDec;
        if (typeof p.declinaison === "number") {
            pDec = p.declinaison;
            const lonR = p.fullDegree * DEG, E = OBLIQUITY * DEG;
            const sinBeta = (Math.sin(pDec * DEG) - Math.sin(E) * Math.sin(lonR)) / Math.cos(E);
            const beta = Math.abs(sinBeta) <= 1 ? Math.asin(sinBeta) : 0;
            const raRad = Math.atan2(Math.sin(lonR) * Math.cos(E) - Math.tan(beta) * Math.sin(E), Math.cos(lonR));
            pRa = ((raRad / DEG) + 360) % 360;
        } else {
            const eq = eclToEq(p.fullDegree, 0);
            pRa = eq.ra;
            pDec = eq.dec;
        }
        const angles = bodyAngles(pRa, pDec);
        planetAnglesMap.push({ name: pName, ra: pRa, dec: pDec, angles });
    });

    const PARAN_LABELS = {
        "Culmination-Culmination": "co-culmination (les deux au MC)",
        "Culmination-Lever": "étoile culmine quand la planète se lève",
        "Lever-Lever": "co-lever (les deux à l'horizon Est)",
        "Lever-Culmination": "planète se lève quand l'étoile culmine",
        "Coucher-Coucher": "co-coucher (les deux à l'horizon Ouest)",
        "Culmination-Coucher": "étoile culmine quand la planète se couche",
        "Coucher-Culmination": "planète se couche quand l'étoile culmine",
        "Lever-Coucher": "étoile se lève quand la planète se couche",
        "Coucher-Lever": "étoile se couche quand la planète se lève",
    };

    etoilesFixesRaw.forEach(star => {
        const sName = star.name?.fr;
        if (!sName) return;
        const sDec = star.declination_j2000;
        const sRa = star.ra_j2000;
        if (sDec == null || sRa == null) return;
        const starAngles = bodyAngles(sRa, sDec);

        planetAnglesMap.forEach(pEntry => {
            pEntry.angles.forEach(pAngle => {
                starAngles.forEach(sAngle => {
                    let diff = Math.abs(pAngle.ramc - sAngle.ramc);
                    if (diff > 180) diff = 360 - diff;
                    if (diff <= PARAN_ORB) {
                        const comboKey = `${sAngle.type}-${pAngle.type}`;
                        paranResults.push({
                            planete: pEntry.name,
                            etoile: sName,
                            etoile_desc: ETOILE_DESC[sName]?.fr || "",
                            etoile_desc_en: ETOILE_DESC[sName]?.en || "",
                            angle_etoile: sAngle.type,
                            angle_planete: pAngle.type,
                            orb: Math.round(diff * 100) / 100,
                            interpretation: PARAN_LABELS[comboKey] || `${sAngle.type} de l'étoile / ${pAngle.type} de la planète`,
                            maison: getHouseNumber(etoilesFixesRaw.find(e => e.name?.fr === sName)?.fullDegree ?? 0),
                            signe_planete: planetes.find(x => (x.planet?.fr || x.planet?.en) === pEntry.name)?.zodiac_sign?.name?.fr || ""
                        });
                    }
                });
            });
        });
    });
}

// ─────────────────────────────────────────────────────────────────
// 6i. DÉCLINAISONS — Hors Limites (OOB), Parallèles, Contre-Parallèles
// ─────────────────────────────────────────────────────────────────
const OOB_THRESHOLD      = OBLIQUITY;
const DECL_ORB_STANDARD  = 1.0;
const DECL_ORB_LUMINAIRE = 1.5;
const LUMINAIRES_DECL    = new Set(["Soleil", "Lune"]);

// Tous les objets ayant un champ declinaison numérique (planètes, Chiron, petits corps, nœuds…)
const planetesDeclinees = planetes.filter(p => typeof p.declinaison === 'number');

// A. Planètes / Objets Hors Limites (OOB)
const planeteOOB = [];
planetesDeclinees.forEach(p => {
    const name = p.planet.fr || p.planet.en;
    if (Math.abs(p.declinaison) > OOB_THRESHOLD) {
        planeteOOB.push({
            planete:     name,
            declinaison: p.declinaison,
            hemisphere:  p.declinaison > 0 ? "Nord" : "Sud",
            depassement: parseFloat((Math.abs(p.declinaison) - OOB_THRESHOLD).toFixed(2))
        });
    }
});

// B. Parallèles (//) et Contre-Parallèles (#)
const paralleles       = [];
const contreParalleles = [];
for (let i = 0; i < planetesDeclinees.length; i++) {
    for (let j = i + 1; j < planetesDeclinees.length; j++) {
        const pA = planetesDeclinees[i], pB = planetesDeclinees[j];
        const nameA = pA.planet.fr || pA.planet.en;
        const nameB = pB.planet.fr || pB.planet.en;
        const hasLuminaire = LUMINAIRES_DECL.has(nameA) || LUMINAIRES_DECL.has(nameB);
        const orb = hasLuminaire ? DECL_ORB_LUMINAIRE : DECL_ORB_STANDARD;
        const sameHemi = Math.sign(pA.declinaison) === Math.sign(pB.declinaison);
        if (sameHemi) {
            const diff = Math.abs(pA.declinaison - pB.declinaison);
            if (diff <= orb) paralleles.push({
                p1: nameA, decl1: pA.declinaison,
                p2: nameB, decl2: pB.declinaison,
                orb: parseFloat(diff.toFixed(2)), hasLuminaire,
                hemisphere: pA.declinaison > 0 ? "Nord" : "Sud"
            });
        } else {
            const diff = Math.abs(Math.abs(pA.declinaison) - Math.abs(pB.declinaison));
            if (diff <= orb) contreParalleles.push({
                p1: nameA, decl1: pA.declinaison,
                p2: nameB, decl2: pB.declinaison,
                orb: parseFloat(diff.toFixed(2)), hasLuminaire
            });
        }
    }
}

// ─────────────────────────────────────────────────────────────────
// 6j. SCORE DE PUISSANCE DES CONFIGURATIONS (tri multi-critères)
// ─────────────────────────────────────────────────────────────────
const OOB_NAMES_SET         = new Set(planeteOOB.map(p => p.planete));
const ETOILE_CONJ_NAMES_SET = new Set(etoileMatches.map(em => em.planete));
const PARA_PAIRS_SET        = new Set([
    ...paralleles.map(p => [p.p1, p.p2].sort().join("|")),
    ...contreParalleles.map(p => [p.p1, p.p2].sort().join("|"))
]);
const ANGLES_POWER_SET = new Set(["Ascendant", "Milieu du Ciel", "Descendant", "Imum Coeli"]);
const HIERARCHY_BASE_SCORE = {
    "Stellium": 30, "Grand Carré": 30, "Grand Trigone": 30,
    "T-Carré": 20, "Cerf-Volant (Kite)": 20, "Yod — Doigt de Dieu": 20,
    "Croix Cardinal": 25, "Croix Fixe": 25, "Croix Mutable": 25
};

configurations.forEach(c => {
    let score = HIERARCHY_BASE_SCORE[c.type] || 10;
    const pList = c.planets || [];
    // Facteur Luminaires
    if (pList.some(p => LUMINAIRES_DECL.has(p)))        score += 50;
    // Facteur Angles
    if (pList.some(p => ANGLES_POWER_SET.has(p)))       score += 40;
    // Facteur Étoile Fixe conjointe
    if (pList.some(p => ETOILE_CONJ_NAMES_SET.has(p)))  score += 30;
    // Facteur OOB
    if (pList.some(p => OOB_NAMES_SET.has(p)))          score += 20;
    // Facteur Parallèle/Contre-Parallèle (double validation — max +20 par figure)
    let paraBonus = false;
    for (let i = 0; i < pList.length && !paraBonus; i++)
        for (let j = i + 1; j < pList.length && !paraBonus; j++)
            if (PARA_PAIRS_SET.has([pList[i], pList[j]].sort().join("|"))) paraBonus = true;
    if (paraBonus) score += 20;
    // Facteur d'exactitude : orbe moyen des aspects internes à la figure
    const figAspects = aspects.filter(a => pList.includes(a.p1) && pList.includes(a.p2));
    if (figAspects.length > 0) {
        const orbeMoyen = figAspects.reduce((s, a) => s + parseFloat(a.exactitude), 0) / figAspects.length;
        score += Math.max(0, Math.round(10 - orbeMoyen * 2));
    }
    c.puissanceScore = score;
    c.prioriteLabel  = score >= 120 ? "PRIORITÉ ABSOLUE" : score >= 80 ? "Majeure" : score >= 50 ? "Significative" : "Mineure";
});
// Tri par score décroissant — les figures les plus puissantes en premier
configurations.sort((a, b) => (b.puissanceScore || 0) - (a.puissanceScore || 0));

// ─────────────────────────────────────────────────────────────────
// 6j-bis. DÉDUPLICATION POST-CALCUL (marquage non-destructif)
// Identifie les sous-configurations géométriquement contenues dans une figure parente.
// Règles : Grand Carré ⊃ T-Carré | Cerf-Volant ⊃ Grand Trigone
// N'affecte ni les scores, ni les aspects, ni le calcul — post-processing uniquement.
// ─────────────────────────────────────────────────────────────────
const PARENT_CHILD_RULES = [
    { parent: "Grand Carré",       child: "T-Carré" },
    { parent: "Cerf-Volant (Kite)", child: "Grand Trigone" }
];
// Passe 1 : relations hiérarchiques (T-Carré ⊂ Grand Carré, Grand Trigone ⊂ Cerf-Volant)
configurations.forEach(child => {
    if (child.subConfigOf) return;
    configurations.forEach(parent => {
        if (child === parent || !parent.planets || !child.planets) return;
        if (!child.planets.every(p => parent.planets.includes(p))) return;
        const rule = PARENT_CHILD_RULES.find(r => r.parent === parent.type && r.child === child.type);
        if (rule) { child.subConfigOf = parent.type; child.subConfigType = "child"; }
    });
});

// Passe 2 : variantes du même type (ex: deux Grand Carrés partageant 3 planètes sur 4)
// Règles de seuil par type :
//   Stellium  → threshold = min (sous-ensemble strict : toutes les planètes du plus petit dans le plus grand)
//   Autres    → threshold = min - 1 (N-1 planètes communes suffisent)
// Pour Stellium : on garde le PLUS GRAND (plus de planètes). Pour les autres : le mieux scoré.
const OVERLAP_TYPES = new Set(["Stellium", "Grand Carré", "T-Carré", "Grand Trigone", "Yod", "Cerf-Volant (Kite)"]);
const confByType = {};
configurations.forEach(c => {
    if (!OVERLAP_TYPES.has(c.type) || c.subConfigOf) return;
    (confByType[c.type] = confByType[c.type] || []).push(c);
});
Object.values(confByType).forEach(group => {
    if (group.length < 2) return;
    for (let i = 0; i < group.length; i++) {
        for (let j = i + 1; j < group.length; j++) {
            const a = group[i], b = group[j];
            if (!a.planets || !b.planets || a.subConfigOf || b.subConfigOf) continue;
            const shared = a.planets.filter(p => b.planets.includes(p));
            const isStellium = a.type === "Stellium";
            // Stellium : threshold = taille du plus petit (sous-ensemble complet requis)
            // Autres   : threshold = min - 1
            const threshold = isStellium
                ? Math.min(a.planets.length, b.planets.length)
                : Math.min(a.planets.length, b.planets.length) - 1;
            if (shared.length >= threshold) {
                let redundant;
                if (isStellium) {
                    // Garder le plus grand Stellium (plus de planètes = plus d'information)
                    redundant = a.planets.length >= b.planets.length ? b : a;
                } else {
                    // Garder le mieux scoré
                    [, redundant] = (a.puissanceScore || 0) >= (b.puissanceScore || 0) ? [a, b] : [b, a];
                }
                redundant.subConfigOf = a.type;
                redundant.subConfigType = "variant";
                redundant.sharedPlanets = shared.length;
            }
        }
    }
});

// ─────────────────────────────────────────────────────────────────
// 6k. SCORE DE PUISSANCE DES ASPECTS INDIVIDUELS (post-enrichissement)
// Calculé ici (après 6b, 6h, 6i) pour avoir accès à tous les contextes :
// angularPlanets, etoileMatches, OOB_NAMES_SET, LUMINAIRES_DECL
// v4.0.0 : modulations rétrogradation, stationnaire, dignité, réception
// ─────────────────────────────────────────────────────────────────
const ASPECT_BASE_SCORES = {
    "Conjonction": 10, "Opposition": 9, "Carré": 8, "Trigone": 7, "Sextile": 6,
    "Quinconce": 3, "Semi-Carré": 2, "Quintile": 2, "Sesqui-Carré": 2,
    "Semi-Sextile": 1, "Biquintile": 1
};
const _stationarySet = new Set(stationaryPlanets.map(sp => sp.planet));
const _receptionPairsAsp = new Set(mutualReceptions.map(mr => [mr.p1, mr.p2].sort().join("|")));
const _uniReceptionMap = {};
["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"].forEach(name => {
    const p = planetes.find(x => x.planet.fr === name);
    if (!p) return;
    const sign = p.zodiac_sign?.name?.fr;
    if (!sign) return;
    Object.entries(dignities).forEach(([otherPlanet, digs]) => {
        if (otherPlanet === name) return;
        if (digs.dom.includes(sign)) {
            if (!_uniReceptionMap[name]) _uniReceptionMap[name] = new Set();
            _uniReceptionMap[name].add(otherPlanet);
        }
    });
});
aspects.forEach(a => {
    const base       = ASPECT_BASE_SCORES[a.aspect] || 1;
    const exactBonus = Math.max(0, Math.round(10 - parseFloat(a.exactitude) * 1.5));
    let bonus = 0;
    if (LUMINAIRES_DECL.has(a.p1)         || LUMINAIRES_DECL.has(a.p2))         bonus += 8;
    if (ANGLES_POWER_SET.has(a.p1)        || ANGLES_POWER_SET.has(a.p2))        bonus += 6;
    if (OOB_NAMES_SET.has(a.p1)           || OOB_NAMES_SET.has(a.p2))           bonus += 4;
    if (ETOILE_CONJ_NAMES_SET.has(a.p1)   || ETOILE_CONJ_NAMES_SET.has(a.p2))  bonus += 5;
    const n1 = PLANET_NATURES[a.p1], n2 = PLANET_NATURES[a.p2];
    if (n1 === "bénéfique" && n2 === "bénéfique") bonus += 2;
    else if (n1 === "maléfique" && n2 === "maléfique") bonus -= 1;

    const _p1Obj = planetes.find(x => (x.planet.fr || x.planet.en) === a.p1);
    const _p2Obj = planetes.find(x => (x.planet.fr || x.planet.en) === a.p2);

    // v4.0 — Rétrogradation : aspect avec planète rétrograde = énergie internalisée, plus significatif
    const _r1 = _p1Obj && (_p1Obj.isRetro === "True" || _p1Obj.isRetro === true);
    const _r2 = _p2Obj && (_p2Obj.isRetro === "True" || _p2Obj.isRetro === true);
    if (_r1 || _r2) { bonus += (_r1 && _r2) ? 3 : 2; a._retroMod = true; }

    // v4.0 — Stationnaire : planète quasi immobile = concentration d'énergie exceptionnelle
    const _st1 = _stationarySet.has(a.p1), _st2 = _stationarySet.has(a.p2);
    if (_st1 || _st2) { bonus += (_st1 && _st2) ? 6 : 4; a._stationMod = true; }

    // v4.0 — Dignité essentielle : seule la dignité forte (Domicile/Exaltation) bonifie le score ; Exil/Chute annoté sans bonus (pérégrin = baseline)
    const _s1 = _p1Obj?.zodiac_sign?.name?.fr, _s2 = _p2Obj?.zodiac_sign?.name?.fr;
    const _d1 = _s1 ? getDignity(a.p1, _s1) : "-", _d2 = _s2 ? getDignity(a.p2, _s2) : "-";
    if (_d1 === "Domicile" || _d1 === "Exaltation") { bonus += 2; a._digMod1 = _d1; }
    if (_d2 === "Domicile" || _d2 === "Exaltation") { bonus += 2; a._digMod2 = _d2; }
    if ((_d1 === "Exil" || _d1 === "Chute")) { a._digMod1 = a._digMod1 || _d1; }
    if ((_d2 === "Exil" || _d2 === "Chute")) { a._digMod2 = a._digMod2 || _d2; }

    // v4.0 — Réception : les deux planètes en réception mutuelle (domicile) → adoucissement, constructivité
    const _aspPairKey = [a.p1, a.p2].sort().join("|");
    if (_receptionPairsAsp.has(_aspPairKey)) { bonus += 3; a._receptionMutual = true; }
    else {
        const _uni1 = _uniReceptionMap[a.p1]?.has(a.p2);
        const _uni2 = _uniReceptionMap[a.p2]?.has(a.p1);
        if (_uni1 || _uni2) { bonus += 1; a._receptionUni = true; }
    }

    a.score        = base + exactBonus + bonus;
    a.prioriteLabel = a.score >= 30 ? "CAPITAL" : a.score >= 20 ? "FORT" : a.score >= 12 ? "MODÉRÉ" : "MINEUR";
    a.prioriteEmoji = a.score >= 30 ? "🔴" : a.score >= 20 ? "🟠" : a.score >= 12 ? "🟡" : "⚪";
});
// Tri global en place — toutes les fonctions avales héritent de cet ordre
aspects.sort((a, b) => b.score - a.score);

// Flag isPromoted — Option B : seuil différencié petits corps vs planètes majeures
// Si au moins UNE des deux planètes est un corps majeur → seuil 20 (FORT)
// Si les DEUX sont des petits corps → seuil 28 (évite le bruit interprétatif)
const SMALL_BODIES_PROMO    = new Set(["Vesta","Cérès","Ceres","Pallas","Junon","Juno","Lilith"]);
const PROMO_THRESHOLD_CORE  = 20;
const PROMO_THRESHOLD_SMALL = 28;
aspects.forEach(a => {
    if (a.isMajor !== false) { a.isPromoted = false; return; }
    const bothSmall = SMALL_BODIES_PROMO.has(a.p1) && SMALL_BODIES_PROMO.has(a.p2);
    const threshold = bothSmall ? PROMO_THRESHOLD_SMALL : PROMO_THRESHOLD_CORE;
    a.isPromoted = a.score >= threshold;
});

// ─────────────────────────────────────────────────────────────────
// 7. MAISONS ET DISPOSITIONS
// ─────────────────────────────────────────────────────────────────
let signToHouses = {}; signs.forEach(s => signToHouses[s.fr] = []);
maisons.forEach((m, i) => {
    let end = maisons[(i+1)%12].degree; if (end < m.degree) end += 360;
    for (let s = Math.floor(m.degree/30); s <= Math.floor(end/30); s++) {
        if (!signToHouses[signs[s%12].fr].includes(m.House)) signToHouses[signs[s%12].fr].push(m.House);
    }
});

let fiches_maisons = [], prompts = {};
maisons.forEach((m, i) => {
    let nextM=maisons[(i+1)%12], start=m.degree, end=nextM.degree; if (end<start) end+=360;
    let s_start=Math.floor(start/30), s_end=Math.floor(end/30);
    let segments = [];

    for (let s=s_start; s<=s_end; s++) {
        let signId  = s % 12;
        let signObj = signs[signId];
        let type    = s===s_start ? "Cuspide" : (s===s_end ? "Fin de Maison" : "Intercepté / Suite");
        let degDebut     = s===s_start ? m.normDegree : 0;
        let decanCuspide = type==="Cuspide" ? (Math.min(Math.floor(degDebut/10),2)+1) : null;

