            let p_sign       = signs[signId].fr;
            let patronName   = signObj.ruler;
            let patronP      = planetes.find(p=>p.planet.fr===patronName);
            let patronData   = (patronName!==name && patronP) ? { nom:patronName, maison:getHouseNumber(patronP.fullDegree) } : null;
            let decanRulerName  = CHALDEAN_DECANS[signs[signId].fr][dIndex];
            let decanRulerP     = planetes.find(p=>p.planet.fr===decanRulerName);
            let decanRulerHouse = decanRulerP ? getHouseNumber(decanRulerP.fullDegree) : "?";
            let isAngular   = angularPlanets.find(ap=>ap.planet===name);
            let isCritical  = criticalPlanets.find(cp=>cp.planet===name);
            let minorStr    = getMinorAspectsStr(name);
            const oobInfo   = planeteOOB.find(o => o.planete === name) || null;
            const declAspects = [
                ...paralleles.filter(p => p.p1 === name || p.p2 === name).map(p => ({
