            const triplicityRuler = getTriplicityRuler(p_sign);
            const triplicityHouse = triplicityRuler ? getHouseNumber(planetes.find(pp => pp.planet.fr === triplicityRuler)?.fullDegree ?? 0) : null;
            const triplicityPart = getTriplicityParticipant(p_sign);
            const triplicityPartHouse = triplicityPart ? getHouseNumber(planetes.find(pp => pp.planet.fr === triplicityPart)?.fullDegree ?? 0) : null;
