        segments.push({ signe:signObj.fr, type, degre_debut:degDebut, decan:decanCuspide, maitre:proprioData, locataires:locatairesData });
    }
    fiches_maisons.push({ maison:m.House, segments });

    // Vérifie si TOUS les segments de cette maison sont sans locataires
