    let houseConfs = configurations.filter(c => segments.some(seg => seg.locataires.some(l => c.planets && c.planets.includes(l.planete))));
    if (houseConfs.length > 0) {
        p += `\n=== CONFIGURATIONS NATALES (planètes de cette maison impliquées, triées par Score de Puissance) ===\n`;
