                            p += `\n          → ${em.desc}`;
                        });
                    }
                    p += `\n`;
                    p += `        - Décan Chaldéen ${l.decan.num}, co-gouverné par ${l.decan.maitre} (M${l.decan.maitreHouse}).\n`;
