// ── C2 : ARBRE DES DISPOSITIONS & DISPOSITEUR FINAL ──
const SIGN_RULER_MAP = {
    "Bélier":"Mars","Taureau":"Vénus","Gémeaux":"Mercure","Cancer":"Lune",
    "Lion":"Soleil","Vierge":"Mercure","Balance":"Vénus","Scorpion":"Pluton",
