};
const DISPOSITOR_PLANETS = ["Soleil","Lune","Mercure","Vénus","Mars","Jupiter","Saturne","Uranus","Neptune","Pluton"];
const dispositorTree = {};
DISPOSITOR_PLANETS.forEach(name => {
    const chain = [];
    let current = name;
    const visited = new Set();
    while (current && !visited.has(current)) {
        visited.add(current);
        const p = planetes.find(x => x.planet.fr === current);
        if (!p) break;
        const sign = p.zodiac_sign?.name?.fr;
        if (!sign) break;
        const ruler = SIGN_RULER_MAP[sign];
        const isInDomicile = getDignity(current, sign) === "Domicile";
        chain.push({ planet: current, sign, ruler, inDomicile: isInDomicile });
        if (isInDomicile) break;
        current = ruler;
    }
    dispositorTree[name] = {
        chain,
        finalDispositor: chain.find(c => c.inDomicile)?.planet || null,
        isLoop: !chain.some(c => c.inDomicile)
    };
});
const finalDispositors = [...new Set(
    Object.values(dispositorTree).map(d => d.finalDispositor).filter(Boolean)
)];
const dispositorStr = finalDispositors.length > 0
    ? `Dispositeur(s) final(aux) : ${finalDispositors.join(", ")} — planète(s) en domicile concentrant le pouvoir de la chaîne de maîtrise. Toute la carte est ultimement « commandée » par ${finalDispositors.length === 1 ? 'cette planète' : 'ces planètes'}.`
