DISPOSITOR_PLANETS.forEach(name => {
    const p = planetes.find(x => x.planet.fr === name);
    if (!p) return;
    const house = getHouseNumber(p.fullDegree);
    const isRetro = p.isRetro?.toLowerCase?.() === 'true' || p.isRetro === true;
    const sign = p.zodiac_sign?.name?.fr;
    let score = 0;
    const details = [];

    if (ANGULAR_HOUSES_SET.has(house))  { score += 5; details.push(`M${house} angulaire +5`); }
    else if (STRONG_HOUSES_SET.has(house)) { score += 4; details.push(`M${house} angulaire +4`); }
