    else if (CADENT_WEAK_HOUSES.has(house)){ score -= 5; details.push(`M${house} cadente faible -5`); }
    else { score += 2; details.push(`M${house} cadente +2`); }

    if (isRetro) { score -= 5; details.push("Rétrograde -5"); }
    else         { score += 4; details.push("Direct +4"); }

    const helio = helioConditions[name];
    if (helio?.condition?.includes("CAZIMI"))    { score += 5; details.push("Cazimi +5"); }
    else if (helio?.condition?.includes("COMBUSTE")) { score -= 5; details.push("Combuste -5"); }
    else if (helio?.condition?.includes("SOUS LES RAYONS")) { score -= 4; details.push("Sous les rayons -4"); }
    else if (name !== "Soleil" && name !== "Lune") { score += 5; details.push("Libre du Soleil +5"); }

    const inMutualReception = mutualReceptions.some(mr =>
        (mr.p1 === name || mr.p2 === name) && mr.type === "domicile"
    );
    if (inMutualReception) { score += 5; details.push("Réception mutuelle domicile +5"); }

    const essentialDig = getDignity(name, sign);
    const essentialScore = essentialDig === "Domicile" ? 5 : essentialDig === "Exaltation" ? 4
        : essentialDig === "Exil" ? -5 : essentialDig === "Chute" ? -4 : 0;
