// ── C4b : PLANÈTES ASSIÉGÉES (entre deux maléfiques) ──
const besiegedPlanets = [];
const sortedByDeg = DISPOSITOR_PLANETS
    .map(name => ({ name, deg: planetes.find(x => x.planet.fr === name)?.fullDegree }))
    .filter(p => p.deg !== undefined)
    .sort((a, b) => a.deg - b.deg);
