    if (MALEFICS_TRAD.has(p.name) || BENEFICS_TRAD.has(p.name)) return;
    const prev = sortedByDeg[(idx - 1 + sortedByDeg.length) % sortedByDeg.length];
    const next = sortedByDeg[(idx + 1) % sortedByDeg.length];
    if (MALEFICS_TRAD.has(prev.name) && MALEFICS_TRAD.has(next.name)) {
        // Vérifier si un bénéfique intercepte le besiegement (atténuation)
        const pDeg = p.deg, prevDeg = prev.deg, nextDeg = next.deg;
        const beneficIntervenes = sortedByDeg.some(bp => {
            if (!BENEFICS_TRAD.has(bp.name)) return false;
            if (prevDeg < nextDeg) return bp.deg > prevDeg && bp.deg < nextDeg;
            return bp.deg > prevDeg || bp.deg < nextDeg;
        });
        const severity = beneficIntervenes ? "ATTÉNUÉE" : "STRICTE";
        besiegedPlanets.push({
            planet: p.name,
            between: [prev.name, next.name],
            severity,
            description: beneficIntervenes
