// ── Parsing de la date ────────────────────────────────────────────────────
// Compatible avec le format DD/MM/YYYY du nœud Extract Variables N8N
function parseDate(s) {
  s = (s || "").trim();
  if (s.includes("/")) {
    const [d, m, y] = s.split("/").map(Number);
    return { year: y, month: m, day: d, hour: 12 };
  } else if (s.includes("T")) {
    const [dp, tp] = s.split("T");
    const [y, m, d] = dp.split("-").map(Number);
    const parts = tp.split(":").map(Number);
    return { year: y, month: m, day: d, hour: (parts[0]||0) + (parts[1]||0)/60 + (parts[2]||0)/3600 };
  } else {
    const [y, m, d] = s.split("-").map(Number);
    return { year: y, month: m, day: d, hour: 12 };
  }
}

// ── Jour Julien (algorithme standard) ────────────────────────────────────
function julianDay(year, month, day, hour) {
  let y = year, mo = month;
  if (mo <= 2) { y -= 1; mo += 12; }
  const A = Math.floor(y / 100);
  const B = 2 - A + Math.floor(A / 4);
  return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (mo + 1)) + day + (hour / 24) + B - 1524.5;
}

// ── Précession générale en longitude depuis J2000.0 ───────────────────────
// Source : IAU 2006 — p = 50.2909"/an × T + 0.000022"/an² × T²
function precessionDeg(jd) {
  const T = (jd - 2451545.0) / 365.25;   // années depuis J2000.0
  return (50.2909 * T + 0.000022 * T * T) / 3600.0;
}

