function lonToSign(lon) {
  const l = ((lon % 360) + 360) % 360;
  const idx = Math.floor(l / 30);
  return {
    fullDegree: Math.round(l * 10000) / 10000,
    normDegree: Math.round((l - idx * 30) * 10000) / 10000,
    sign_index: idx,
    zodiac_sign: { number: idx + 1, name: { fr: SIGNES_FR[idx], en: SIGNES_EN[idx] } }
